-- =============================================================
-- 项目办结时间：单列修改权限 + 默认授权
-- 背景：办结时间是产值归属月份 / 回款应收账期 / 欠款逾期天数的分片轴，
--       不能复用 edit 权限（"已办结不可改"的通用规则会把人工修正挡死），
--       因此新增按钮级权限 project:project:closeTime，默认只给超管与生产管理。
-- 执行库：xky_project (PostgreSQL)
-- 幂等：可重复执行
--
-- ⚠️ menu_id 不要写死：sys_menu.menu_id 是 IDENTITY 自增列
--    （sql/2_create_table.sql:168 `menu_id BIGINT GENERATED BY DEFAULT AS IDENTITY`，
--     序列 sys_menu_menu_id_seq，见 sql/3_init_sys_data.sql:128 的 setval）。
--    只有建库初始化脚本（如 5_init_proj_menu.sql）才能用固定 id，
--    增量脚本必须交给自增，否则会撞上已有菜单的主键。
--    写法与 sql/29_add_db_backup_menu.sql 保持一致。
-- =============================================================

do $$
declare
    v_menu_id bigint;
begin
    -- 1) 序列对齐：解决"写死 id"的另一半隐患
    --    序列当前值可能小于表内最大值，nextval 照样会吐出一个已存在的主键。
    --    这里先把序列对齐到「当前最大 menu_id」，保证取到的下一个值必定是空号。
    --    ⚠️ PL/pgSQL 里没有 INTO 的裸 SELECT 会报 "query has no destination for result data"，
    --       必须写成 perform。
    perform setval(
        pg_get_serial_sequence('sys_menu', 'menu_id')::regclass,
        greatest(
            coalesce((select max(menu_id) from sys_menu), 0),
            coalesce((select last_value from sys_menu_menu_id_seq), 0)
        )
    );

    -- 2) 误授权清理：本脚本早期版本把 menu_id 写死成 1103，若当时在非事务模式下跑过，
    --    后续语句可能给「库里占用着 1103 的其它菜单」误插了生产管理授权，这里回收。
    delete from sys_role_menu rm
    where rm.menu_id = 1103
      and exists (
            select 1 from sys_menu m
            where m.menu_id = rm.menu_id
              and coalesce(m.perms, '') <> 'project:project:closeTime'
      );

    -- 3) 判重：按钮(F)不显示在菜单树里，只能按 perms 识别
    select menu_id into v_menu_id
    from sys_menu
    where perms = 'project:project:closeTime'
    limit 1;

    if v_menu_id is null then
        -- 新建按钮级权限：挂在「项目列表」503 下，order_num=7 排在「项目办结」之后
        insert into sys_menu(menu_name, parent_id, order_num, path, component, route_name,
                             is_frame, is_cache, menu_type, visible, status, perms, icon,
                             create_by, create_time, remark)
        values ('办结时间修改', 503, 7, '', '', '',
                1, 0, 'F', '0', '0', 'project:project:closeTime', '#',
                'admin', now(), '人工修正已办结/已归档项目的办结时间（受限操作，走操作日志留痕）')
        returning menu_id into v_menu_id;

        raise notice '[ok] 已创建菜单「办结时间修改」，menu_id=%', v_menu_id;
    else
        raise notice '[skip] 权限已存在，menu_id=%，仅补角色授权', v_menu_id;
    end if;

    -- 4) 授权给「生产管理」角色（角色名不匹配则影响 0 行，不报错；请按实际角色名调整）
    insert into sys_role_menu(role_id, menu_id)
    select r.role_id, v_menu_id
    from sys_role r
    where r.role_name = '生产管理'
      and not exists (
            select 1 from sys_role_menu rm
            where rm.role_id = r.role_id and rm.menu_id = v_menu_id
      );

    -- ⚠️ 超级管理员（role_id=1）走 RuoYi 的 *:*:* 白名单自动放行，无需授权。

    raise notice '[ok] project:project:closeTime 就绪，menu_id=%', v_menu_id;
end $$;

-- =============================================================
-- 执行前：建议先看看你库里 menu_id=1103 被谁占了（报错就是它撞的）
-- SELECT menu_id, menu_name, parent_id, perms FROM sys_menu WHERE menu_id = 1103;
--
-- 执行（DO 块内部按编号依次做）：
--   1) 序列对齐   2) 清理误授权   3) 判重   4) 建菜单取 id + 授权生产管理
-- 输出看控制台的 NOTICE 行即可。
-- =============================================================

-- =============================================================
-- 验收
-- =============================================================

-- A) 确认权限已注册（menu_id 由自增分配，不要按 1103 找）
select menu_id, menu_name, parent_id, perms, order_num
from sys_menu
where perms = 'project:project:closeTime';

-- B) 哪些角色拿到了该权限（超管不在列表里属正常：走 *:*:* 白名单）
select r.role_id, r.role_name, r.role_key
from sys_role r
join sys_role_menu rm on rm.role_id = r.role_id
where rm.menu_id = (select menu_id from sys_menu where perms = 'project:project:closeTime' limit 1)
order by r.role_id;

